    box.append(title, form, ul, pager, dropRow);
    const syncDrop = () => { const d = dropLoad(); dropOn.checked = d.on; dropFreq.value = d.freq; dropRow.classList.toggle('is-on', d.on); };
    dropOn.addEventListener('change', () => {
