        who.append(h('b', null, e.name || 'anon'));
        if (e.visit) { li.classList.add('is-visit'); const m = h('em', null, ' ✧'); m.title = 'dropped by on their own'; who.append(m); }
        if (e.id) who.append(h('i', null, ` @${e.id.replace(/^@/, '')}`));
        head.append(avatarEl(e), who);
